import os

OUT = '/Users/lzy/pro/solo/workspaces/zy72149/test-data/合同截图_曲目清单.jpg'

# 最小合法 JPEG：SOI + APP0(JFIF) + 2xDQT + SOF0 + 4xDHT + SOS + 1 字节图像数据 + EOI
jpg = bytes.fromhex(
    'ffd8'  # SOI
    'ffe000104a46494600010100000100010000'  # APP0 JFIF
    'ffdb004300' + '080606070605080707070909080a0c140d0c0b0b0c1912130f141d1a1f1e1d1a1c1c20242e2720222c231c1c2837292c30313434341f27393d38323c2e333432'  # DQT0
    'ffdb004301' + '0909090c0b0c180d0d1832211c21323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232323232'  # DQT1
    'ffc00011080001000103012200021101031101'  # SOF0 1x1
    'ffc4001f0000010501010101010100000000000000000102030405060708090a0b'  # DHT DC0
    ''  # DHT AC0
    'ffc4001f010003010101010101010101000000000000000102030405060708090a0b'  # DHT DC1
    ''  # DHT AC1
    'ffda000c03010002110311003f00fbd21a3b2800'  # SOS + 图像数据
    'ffd9'  # EOI
)

with open(OUT, 'wb') as f:
    f.write(jpg)

# 验证
with open(OUT, 'rb') as f:
    head = f.read(2)
    assert head[0] == 0xff and head[1] == 0xd8, f'Bad JPG header: {head.hex()}'
print(f'wrote {len(jpg)} bytes valid JPG -> {OUT}')
